{
  "implementation": "def solve(case):
    items = case['items']
    required = set(case['required_failure_items'])
    unresolved = set(case['unresolved_without'])
    def outcome(indices):
        config = set(items[i] for i in indices)
        for u in unresolved:
            if u not in config:
                return 'UNRESOLVED'
        if required.issubset(config):
            return 'FAIL'
        return 'PASS'
    full = list(range(len(items)))
    tests = 1
    if outcome(full) != 'FAIL':
        raise ValueError
    current = full
    n = 2
    while True:
        n = min(n, len(current))
        k = len(current) // n
        subsets = [current[i*k:(i+1)*k if i != n-1 else len(current)] for i in range(n)]
        reduced = False
        for sub in subsets:
            tests += 1
            if outcome(sub) == 'FAIL':
                current = sub
                n = 2
                reduced = True
                break
        if reduced:
            continue
        for sub in subsets:
            complement = [x for x in current if x not in sub]
            tests += 1
            if outcome(complement) == 'FAIL':
                current = complement
                n = max(2, n-1)
                reduced = True
                break
        if reduced:
            continue
        if n * 2 <= len(current):
            n *= 2
        else:
            n = len(current)
        if n >= len(current):
            break
    return {
        'minimal_failure': [items[i] for i in current],
        'outcome': outcome(current),
        'tests': tests
    }"
}
